extern void readAnimFrameCount(GameObject *);
extern void playSFX(s32);
extern void tickAnimation(GameObject *);

void func_80119EF0(GameObject *o)
{
    switch (o->state) {
    case 0:
        switch (o->subState) {
        case 0:
            o->subState++;
            o->tpage = 9;
            o->unkD = 0x80;
            o->spriteBank = ((s32*)&(*(SPADBlock_19EF0 *)&SCRATCHPAD).i2d4)[0];
            o->anim = D_80134030[o->subtype];
            readAnimFrameCount(o);
            o->timer = nextRandom() & 3;
            if ((o->animFrame >> 1) & 1) {
                if (GAME.selectedSection < 4) {
                    playSFX(0x7d);
                } else {
                    playSFX(0x85);
                }
            }
            break;
        case 1:
            if (--o->timer == -1) {
                o->subState = 0;
                o->state++;
            }
            break;
        }
        break;
    case 1:
        if (func_80022E44(o)) tickAnimation(o);
        break;
    case 2:
        break;
    case 3:
        freeObjectLayer3(o);
        break;
    }
}

